if mibBuilder.loadTexts: memUsageEntry.setStatus('mandatory')
if mibBuilder.loadTexts: memUsageEntry.setDescription('An entry in the memUsageTable. The index of the entry is slotId.\n          An entry represents the memory usage of the board in the slot.\n          The memory usage includes total size and used size respectively.\n          The solt can be NT slot or LT slot.')
