asamSystemAccessOperatorID = MibScalar((1, 3, 6, 1, 4, 1, 637, 61, 1, 9, 33), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 65535))).setMaxAccess("readwrite")
