asamSuperuserAuthByTacacsPlus = MibScalar((1, 3, 6, 1, 4, 1, 637, 61, 1, 9, 50), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("enabled", 1), ("disabled", 2))).clone('disabled')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: asamSuperuserAuthByTacacsPlus.setStatus('mandatory')
if mibBuilder.loadTexts: asamSuperuserAuthByTacacsPlus.setDescription('The TL1/CLI user ID SUPERUSER/isadmin is optionally authenticated by\n         Tacacs+ based protocol on this object. When disabled, SUPERUSER/isadmin\n         is always authenticated by the local user database. When enabled,\n         SUPERUSER/isadmin authentication is initially attempted with Tacacs+,but\n         the authentication will fall back to the local TL1/CLI user database, if\n         all Tacacs+ servers are disabled, or the Tacacs+ servers are not\n         responding successfully to the authentication request.\n         Note that Tacacs+ is applicable only for CLI user from R5.2 onwards.\n\n            ALCATEL NOTE:\n              SUPPORT: YES\n              PERSIST: YES\n              INSRVMOD: NA\n              RANGE: 1..2\n              DEFVALUE: 2\n              UNITS: NA')
asamExternalLedsStatus = MibScalar((1, 3, 6, 1, 4, 1, 637, 61, 1, 9, 51), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("enabled", 1), ("disabled", 2))).clone('enabled')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: asamExternalLedsStatus.setStatus('mandatory')
if mibBuilder.loadTexts: asamExternalLedsStatus.setDescription("This MIB object is used to administratively turn off LEDs which are visible from the\n         outside on some equipment practices like sealed remotes. By default, LEDs are enabled which\n         means they are working normally and represent the actual status of the concerned item. If\n         LEDs are disabled, they won't show any light even though an error status should be reported.\n\n         This MIB object is only supported on some equipment practices. If not supported this\n         MIB object will return enabled when read.\n\n            ALCATEL NOTE:\n              SUPPORT: YES\n              PERSIST: YES\n              INSRVMOD: NA\n              RANGE: 1..2\n              DEFVALUE: 1\n              UNITS: NA")
